var i=`0078-sarmale`;var a=`world-0078`;var t=`RO`;var o=`eastern-europe`;var r=4;var l=133;var s={en:`Sarmale`,ua:`Сармале`};var g={en:`A classic dish from Romania, featuring sauerkraut, ground pork, white rice, yellow onion. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Румунія. Основні складники: квашена капуста, свинячий фарш, білий рис, жовта цибуля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Separate and blanch the leaves in hot water for about 6 minutes until pliable. Drain and trim thick ribs.`,ua:`Відокремте й бланшуйте листя в гарячій воді приблизно 6 хвилин до гнучкості. Обсушіть і зріжте товсті прожилки.`,t:[`blanching`],m:6,i:[[`sauerkraut`,900,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-pork`,500,`g`],[`white-rice`,145,`g`],[`yellow-onion`,155,`g`],[`dill`,20,`g`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:22,i:[]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 90 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 90 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:90,i:[[`tomato-passata`,400,`g`],[`water`,600,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`sour-cream`,180,`g`]]}];var d={slug:i,id:a,country:`RO`,region:o,servings:4,minutes:133,title:s,text:g,steps:u};export{t as country,d as default,a as id,l as minutes,o as region,r as servings,i as slug,u as steps,g as text,s as title};